const photo=(album:string,id:string,shape='landscape')=>{const width=shape==='portrait'?480:shape==='wide'?1600:960,height=shape==='portrait'?720:shape==='wide'?400:640;return {id,src:`/assets/photos/${album}-${id}.png`,width,height,variants:[{src:`/assets/photos/${album}-${id}-small.png`,width:width/2,height:height/2}],alt:`合成测试图 ${id}，不是真实照片`,draft:false,approved:true,caption:id==='b'?'用于验证长注释换行与纵向滚动。'.repeat(35):undefined};};
export const fixtureAlbums=[3,1,2,12,3,3].map((count,i)=>{const slug=`synthetic-${i+1}`;return {slug,title:i===5?'合成测试影集：很长的名称应自然换行并保持所有文字完整可读，不裁切也不省略':'合成测试影集 '+(i+1),description:'仅供隔离测试的几何图，非用户影集。',...(i===0?{coverPosition:{x:50,y:100}}:{}),draft:false,approved:true,order:i,periodLabel:'合成夹具',photos:Array.from({length:count},(_,n)=>photo(slug,String.fromCharCode(97+n),['landscape','portrait','wide'][n%3]))};});
fixtureAlbums[0].photos.splice(1,0,{...photo('private-photo-sentinel','secret'),alt:'PRIVATE-MIXED-ALT-SENTINEL',draft:true,approved:false});
export const hiddenFixtures=[{slug:'synthetic-empty',title:'PRIVATE-EMPTY-SENTINEL',description:'',draft:false,approved:true,photos:[]},{slug:'synthetic-secret',title:'PRIVATE-TITLE-SENTINEL',description:'PRIVATE-DESCRIPTION',draft:true,approved:false,photos:[{...photo('private-photo-sentinel','secret'),alt:'PRIVATE-ALT-SENTINEL'}]}];
